<script setup lang="ts">import { computed, onMounted, ref } from "vue"; import { useRoute } from "vue-router"; import { ElMessage } from "element-plus"; import { get, post } from "@/api/client"; import type { Order } from "@/types"; const route = useRoute(); const order = ref<Order | null>(null); const id = computed(() => String(route.params.id)); onMounted(async () => { order.value = await get<Order>(`/sales-orders/${id.value}`) }); async function action(name: string): Promise<void> { await post(`/sales-orders/${id.value}/${name}`); ElMessage.success("操作成功") }</script>
<template><el-card v-if="order"><template #header>销售订单 {{ order.order_no }}</template><el-descriptions :column="2" border><el-descriptions-item label="客户">{{ order.customer_id }}</el-descriptions-item><el-descriptions-item label="状态">{{ order.status }}</el-descriptions-item><el-descriptions-item label="预计日期">{{ order.expected_date }}</el-descriptions-item></el-descriptions><div class="actions"><el-button v-for="name in ['submit', 'approve', 'reject', 'cancel']" :key="name" @click="action(name)">{{ name }}</el-button><el-button type="primary" @click="action('ship')">发货</el-button></div></el-card><el-skeleton v-else :rows="5" animated /></template>
